@props([
    'name' => null,
    'value' => null,
    'currency' => null,
    'locale' => null,
    'precision' => null,
    'mode' => 'cents',
    'invalid' => false,
    'size' => null,
])

@aware([
    'fieldInvalid' => false,
])

@php
    use Illuminate\Support\Number;
    use App\Support\Stencil\Form\FormControlClassMap;
    use App\Support\Stencil\Interaction\InteractionStateAttributes;

    $invalid = $invalid || $fieldInvalid;

    $currencyCode = filled($currency) ? (string) $currency : Number::defaultCurrency();
    $localeCode = filled($locale) ? (string) $locale : Number::defaultLocale();

    if (! filled($localeCode)) {
        $localeCode = str_replace('-', '_', (string) app()->getLocale());
    }

    $fractionDigits = $precision ?? 2;
    $fractionDigits = max(0, (int) $fractionDigits);

    $mode = in_array($mode, ['cents', 'decimal'], true) ? $mode : 'cents';

    $numericValue = null;

    if ($value !== null && $value !== '') {
        if (is_numeric($value)) {
            $numericValue = (float) $value;
        }
    }

    $displayValue = $numericValue !== null
        ? Number::currency($numericValue, $currencyCode, $localeCode, $precision)
        : '';

    $hiddenValue = $numericValue !== null
        ? number_format($numericValue, $fractionDigits, '.', '')
        : '';

    $localeForJs = str_replace('_', '-', $localeCode);

    $formControl = app(FormControlClassMap::class);
    $interactionState = app(InteractionStateAttributes::class);

    $userClass = $attributes->get('class');
    $applyFullWidth = ! filled($userClass);

    $controlClasses = collect([
        'input__control',
        'input-currency__control',
        'flex w-full min-w-0',
        $formControl->fieldSurfaceClasses($size),
        'placeholder:text-zinc-500 dark:placeholder:text-zinc-400',
        $formControl->invalidFieldClasses(),
        $invalid ? 'border-red-500 focus-visible:ring-red-500/20 dark:border-red-500' : null,
    ])->filter()->implode(' ');

    $wrapperClasses = collect([
        'input',
        'input-currency',
        'relative flex min-w-0 items-stretch overflow-visible',
        $applyFullWidth ? 'w-full' : null,
        $userClass,
    ])->filter()->implode(' ');

    $controlExtraClass = $attributes->get('class:input') ?? $attributes->get('input:class');

    $controlAttributes = $interactionState->apply(
        $attributes
            ->except(['class', 'class:input', 'input:class', 'name', 'value', 'currency', 'locale', 'precision', 'mode'])
            ->class([$controlClasses, $controlExtraClass])
            ->merge([
                'type' => 'text',
                'inputmode' => 'numeric',
                'autocomplete' => 'off',
                'value' => $displayValue,
                'data-input-control' => true,
                'data-input-currency-display' => true,
            ]),
    );

    if ($invalid) {
        $controlAttributes = $controlAttributes->merge(['aria-invalid' => 'true']);
    }
@endphp

<div
    @class([$wrapperClasses])
    data-input
    data-input-currency
    data-input-currency-mode="{{ $mode }}"
    data-input-currency-locale="{{ $localeForJs }}"
    data-input-currency-currency="{{ $currencyCode }}"
    data-input-currency-precision="{{ $fractionDigits }}"
>
    <input
        type="hidden"
        data-input-currency-value
        @if (filled($name)) name="{{ $name }}" @endif
        @if ($hiddenValue !== '') value="{{ $hiddenValue }}" @endif
    />

    <input {{ $controlAttributes }} />
</div>

/**
 * Stencil — currency input (formatted display, float hidden value).
 */

const INPUT_CURRENCY_SELECTOR = '[data-input-currency]';
const initialized = new WeakSet();

/**
 * @param {ParentNode} root
 */
export function initInputCurrencies(root = document) {
    root.querySelectorAll(INPUT_CURRENCY_SELECTOR).forEach((element) => {
        if (!(element instanceof HTMLElement)) {
            return;
        }

        if (initialized.has(element)) {
            return;
        }

        initialized.add(element);
        bindInputCurrency(element);
    });
}

/**
 * @param {HTMLElement} root
 */
function bindInputCurrency(root) {
    const mode = root.getAttribute('data-input-currency-mode') || 'cents';
    const locale = root.getAttribute('data-input-currency-locale') || 'en-US';
    const currency = root.getAttribute('data-input-currency-currency') || 'USD';
    const precision = parseInt(root.getAttribute('data-input-currency-precision') || '2', 10);

    /** @type {HTMLInputElement | null} */
    const hidden = root.querySelector('[data-input-currency-value]');
    /** @type {HTMLInputElement | null} */
    const display = root.querySelector('[data-input-currency-display]');

    if (!(hidden instanceof HTMLInputElement) || !(display instanceof HTMLInputElement)) {
        return;
    }

    if (display.readOnly || display.disabled) {
        return;
    }

    const scale = 10 ** precision;

    const formatter = new Intl.NumberFormat(locale, {
        style: 'currency',
        currency,
        minimumFractionDigits: precision,
        maximumFractionDigits: precision,
    });

    /**
     * @param {number} minorUnits
     */
    function minorToFloat(minorUnits) {
        return minorUnits / scale;
    }

    /**
     * @param {number} amount
     */
    function floatToMinor(amount) {
        return Math.round(amount * scale);
    }

    /**
     * @param {number} minorUnits
     */
    function syncFromMinor(minorUnits) {
        if (minorUnits <= 0) {
            hidden.value = '';
            display.value = '';

            return;
        }

        const floatValue = minorToFloat(minorUnits);
        hidden.value = floatValue.toFixed(precision);
        display.value = formatter.format(floatValue);
    }

    function readInitialMinor() {
        const raw = hidden.value.trim();

        if (raw === '') {
            return 0;
        }

        const parsed = Number.parseFloat(raw);

        if (! Number.isFinite(parsed)) {
            return 0;
        }

        return Math.max(0, floatToMinor(parsed));
    }

    let minorUnits = readInitialMinor();

    if (mode !== 'cents') {
        return;
    }

    display.addEventListener('keydown', (event) => {
        if (event.ctrlKey || event.metaKey || event.altKey) {
            return;
        }

        const key = event.key;

        if (key === 'Tab' || key === 'Escape' || key.startsWith('Arrow') || key === 'Home' || key === 'End') {
            return;
        }

        if (key === 'Backspace' || key === 'Delete') {
            event.preventDefault();
            minorUnits = Math.floor(minorUnits / 10);
            syncFromMinor(minorUnits);

            return;
        }

        if (key.length === 1 && key >= '0' && key <= '9') {
            event.preventDefault();
            const digit = key.charCodeAt(0) - 48;
            minorUnits = minorUnits * 10 + digit;
            syncFromMinor(minorUnits);
        } else if (key.length === 1) {
            event.preventDefault();
        }
    });

    display.addEventListener('paste', (event) => {
        event.preventDefault();
        const text = event.clipboardData?.getData('text') ?? '';
        const digits = text.replace(/\D/g, '');

        if (digits === '') {
            return;
        }

        minorUnits = Number.parseInt(digits, 10);

        if (! Number.isFinite(minorUnits)) {
            minorUnits = 0;
        }

        syncFromMinor(minorUnits);
    });

    display.addEventListener('input', (event) => {
        event.preventDefault();
    });
}

document.addEventListener('stencil:mount', (event) => {
    if (!(event instanceof CustomEvent)) {
        return;
    }

    const mountRoot = event.detail?.root;

    if (!(mountRoot instanceof HTMLElement)) {
        return;
    }

    initInputCurrencies(mountRoot);
});

if (typeof document !== 'undefined') {
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', () => initInputCurrencies());
    } else {
        initInputCurrencies();
    }
}
